window.SAOMD_STORIES[410400801]={"id":410400801,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410400801:1:1","speaker":"Alice","text":"Kirito! Asuna!\nI demand an explanation!","pose":10540101,"background":"bg_event_urtharbrunnr","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"桐人！ 亚丝娜！我要求一个解释！"},{"uid":"410400801:1:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":2,"order":2,"actions":[{"uid":"410400801:2:1","speaker":"Alice","text":"Why have we left the Dread Bastion\nto return to this place?!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们为什么离开恐惧堡垒又回到这个地方？！"}]},{"id":3,"order":3,"actions":[{"uid":"410400801:3:1","speaker":"Eugeo","text":"I'm with Alice on this one. We ran\ninto another group of fairies in\nthere.","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我支持爱丽丝。我们在那里遇到了另一群仙女。"}]},{"id":4,"order":4,"actions":[{"uid":"410400801:4:1","speaker":"Eugeo","text":"They were trying to get their\nhands on the Divine Object too,\nand they were pushing hard.","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"他们也想拿到神器，而且他们很努力。"}]},{"id":5,"order":5,"actions":[{"uid":"410400801:5:1","speaker":"Eugeo","text":"I'm sure you have a reason for\nthis, but I'd very much appreciate\nyou keeping us in the loop.","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我相信你这样做是有原因的，但我非常感谢你让我们了解情况。"},{"uid":"410400801:5:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":6,"order":6,"actions":[{"uid":"410400801:6:1","speaker":"Kirito","text":"I'm sorry... It's not that I don't\nwant to tell you.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"对不起……我不是不想告诉你。"},{"uid":"410400801:6:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":7,"order":7,"actions":[{"uid":"410400801:7:1","speaker":"Kirito","text":"It's just... I can't really find\nthe words...","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"只是……实在找不到词语来形容……"}]},{"id":8,"order":8,"actions":[{"uid":"410400801:8:1","speaker":"Kirito","text":"I know this isn't exactly fair to\nyou, but I hope you forgive me.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我知道这对你不太公平，但我希望你能原谅我。"}]},{"id":9,"order":9,"actions":[{"uid":"410400801:9:1","speaker":"Asuna","text":"Kirito...","pose":10020909,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人..."}]},{"id":10,"order":10,"actions":[{"uid":"410400801:10:1","speaker":"Kirito","text":"I need to know more about the\nDivine Objects, and the lady who\nknows the most about them...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我需要更多地了解神器，以及最了解他们的女士......"}]},{"id":11,"order":11,"actions":[{"uid":"410400801:11:1","speaker":"Kirito","text":"Is right over there.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"就在那边。"},{"uid":"410400801:11:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":12,"order":12,"actions":[{"uid":"410400801:12:1","speaker":"Alice","text":"Huh...?","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"啊……？"},{"uid":"410400801:12:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":13,"order":13,"actions":[{"uid":"410400801:13:1","speaker":"Urdr","text":"Brave warriors, I am happy to see\nyou here once more.","pose":20330104,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"勇敢的战士们，很高兴再次在这里见到你们。"}]},{"id":14,"order":14,"actions":[{"uid":"410400801:14:1","speaker":"Eugeo","text":"The goddess...","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"女神……"},{"uid":"410400801:14:2","speaker":"Alice","text":"","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":15,"order":15,"actions":[{"uid":"410400801:15:1","speaker":"Asuna","text":"There is still so much we don't\nknow about the Divine Objects.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"关于神器，我们还有很多不了解的地方。"},{"uid":"410400801:15:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":16,"order":16,"actions":[{"uid":"410400801:16:1","speaker":"Asuna","text":"So Kirito thought we should ask\nUrdr here to fill us in.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"所以桐人觉得应该请乌尔德来帮我们填写。"},{"uid":"410400801:16:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":17,"order":17,"actions":[{"uid":"410400801:17:1","speaker":"Alice","text":"I see... Truth be told, I too am\ncurious to learn why so much was\nleft unsaid. The curse, for one.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我明白了……说实话，我也很好奇为什么这么多话没说出来。其中之一就是诅咒。"},{"uid":"410400801:17:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":18,"order":18,"actions":[{"uid":"410400801:18:1","speaker":"Alice","text":"Urdr, I beseech you. Tell us: why\ndid you not reveal the nature of\nthe Divine Objects' powers to us?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"乌尔德，求你了。告诉我们：为什么你不向我们透露神器的能力本质？"},{"uid":"410400801:18:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":19,"order":19,"actions":[{"uid":"410400801:19:1","speaker":"Urdr","text":"I apologize for keeping silent.\nHowever, the curse you speak of\nwas a surprise even to us gods.","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"我为保持沉默而道歉。不过，你所说的诅咒，连我们神都感到惊讶。"}]},{"id":20,"order":20,"actions":[{"uid":"410400801:20:1","speaker":"Urdr","text":"The seven Divine Objects are holy\nvessels, forged to imprison dark\nand malevolent forces.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"七艘神器是神圣的器皿，是为了囚禁黑暗和邪恶势力而铸造的。"}]},{"id":21,"order":21,"actions":[{"uid":"410400801:21:1","speaker":"Urdr","text":"Enshrined within the Hill Giants'\nancient temple, their power united\nto form an unbreakable seal.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"供奉在山丘巨人古老的神殿内，他们的力量联合起来形成了牢不可破的封印。"}]},{"id":22,"order":22,"actions":[{"uid":"410400801:22:1","speaker":"Urdr","text":"However, thieves snuck into the\ntemple and stole them, scattering\nthem to the four winds.","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"然而，盗贼潜入寺庙偷走了它们，并将它们散落在四风中。"}]},{"id":23,"order":23,"actions":[{"uid":"410400801:23:1","speaker":"Urdr","text":"No longer linked, the power of the\nseals began to fade, and the evil\nwithin began to break free.","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"不再相连，封印的力量开始消退，内心的邪恶开始挣脱。"}]},{"id":24,"order":24,"actions":[{"uid":"410400801:24:1","speaker":"Kirito","text":"So in other words, it's not really\na curse?","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也就是说，这并不是真正的诅咒？"},{"uid":"410400801:24:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":25,"order":25,"actions":[{"uid":"410400801:25:1","speaker":"Asuna","text":"Wait, it isn't? But powerful\nmonsters did appear around them,","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"等等，不是吗？但他们的周围确实出现了强大的怪物，"}]},{"id":26,"order":26,"actions":[{"uid":"410400801:26:1","speaker":"Asuna","text":"and Liz's magic evil-repelling\namulet did seem to work...\nAt least a little bit.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"还有莉兹的神奇辟邪符好像确实有作用……至少有一点。"},{"uid":"410400801:26:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":27,"order":27,"actions":[{"uid":"410400801:27:1","speaker":"Urdr","text":"The beasts you encountered were\nservants of the dark beings still\ntrapped within the Divine Objects.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"你遇到的野兽是仍然被困在神器内的黑暗生物的仆人。"}]},{"id":28,"order":28,"actions":[{"uid":"410400801:28:1","speaker":"Urdr","text":"They were summoned to destroy the\nDivine Objects, to release the\ntrue power of the darkness inside.","pose":20330105,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"他们被召唤来摧毁神器，释放内部黑暗的真正力量。"}]},{"id":29,"order":29,"actions":[{"uid":"410400801:29:1","speaker":"Alice","text":"Which means the more Divine\nObjects we find, the greater\ndanger we're in.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"也就是说，找到的神物越多，危险就越大。"},{"uid":"410400801:29:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":30,"order":30,"actions":[{"uid":"410400801:30:1","speaker":"Urdr","text":"That is correct.\nI have put you in great peril...","pose":20330106,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"没错。我已经让你陷入了巨大的危险之中……"}]},{"id":31,"order":31,"actions":[{"uid":"410400801:31:1","speaker":"Alice","text":"The danger is negligible. I'm more\nconcerned that weaker warriors\nthan we may find them first.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"危险可以忽略不计。我更担心比我们弱的战士可能会先找到他们。"},{"uid":"410400801:31:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":32,"order":32,"actions":[{"uid":"410400801:32:1","speaker":"Eugeo","text":"I second Alice here. We know what\nwe have to do now, and we need to\ndouble-time it.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我这里第二个爱丽丝。我们知道我们现在必须做什么，我们需要加倍努力。"}]},{"id":33,"order":33,"actions":[{"uid":"410400801:33:1","speaker":"Eugeo","text":"We have to find all seven Divine\nObjects, then seal these evil\nbeings back inside-for good.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我们必须找到全部七件神物，然后将这些邪恶生物永远封印在里面。"},{"uid":"410400801:33:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":34,"order":34,"actions":[{"uid":"410400801:34:1","speaker":"Kirito","text":"You got it. Thank you, Urdr.\nHold on just a little longer.\nWe only need four more.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"明白了。谢谢你，乌尔德。再坚持一会儿。我们只需要另外四个。"},{"uid":"410400801:34:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":35,"order":35,"actions":[{"uid":"410400801:35:1","speaker":"Asuna","text":"We can't risk monsters showing up\nin Jotunheimr, so we'll hold onto\nthe ones we have for now.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们不能冒险让怪物出现在幽兹海姆，所以我们暂时保留现有的怪物。"},{"uid":"410400801:35:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":36,"order":36,"actions":[{"uid":"410400801:36:1","speaker":"Urdr","text":"Thank you, warriors, fairy and\nhuman... The fate of the world\nrests in your hands.","pose":20330104,"background":"","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"谢谢你们，战士们、精灵们和人类……世界的命运掌握在你们手中。"}]},{"id":37,"order":37,"actions":[{"uid":"410400801:37:1","speaker":"Player A","text":"Gaaah!!","pose":2,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"玩家A","text_zh":"啊啊！！"},{"uid":"410400801:37:2","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400801:37:3","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":38,"order":38,"actions":[{"uid":"410400801:38:1","speaker":"Player B","text":"S-Save us!!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家B","text_zh":"救、救救我们！！"}]},{"id":39,"order":39,"actions":[{"uid":"410400801:39:1","speaker":"Monster","text":"Graaawr!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"吼啊啊！"}]},{"id":40,"order":40,"actions":[{"uid":"410400801:40:1","speaker":"Kirito","text":"What's going on here?!","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这是怎么回事？！"}]},{"id":41,"order":41,"actions":[{"uid":"410400801:41:1","speaker":"Asuna","text":"Something's got these players\nrunning scared!","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"有什么东西让这些玩家吓跑了！"},{"uid":"410400801:41:2","speaker":"Kirito","text":"","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":42,"order":42,"actions":[{"uid":"410400801:42:1","speaker":"Eugeo","text":"Hey, over there! I've never seen\nthat type of monster before!","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嘿，那边！我从来没有见过这种怪物！"},{"uid":"410400801:42:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":43,"order":43,"actions":[{"uid":"410400801:43:1","speaker":"Alice","text":"It seems far more fearsome than\nthose somewhat ridiculous demons\nwe fought here the other day.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"看起来比我们前几天在这里战斗的那些有点可笑的恶魔要可怕得多。"}]},{"id":44,"order":44,"actions":[{"uid":"410400801:44:1","speaker":"Alice","text":"It appears to be more closely\nrelated to the normal monsters\nwe've fought in other places.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"看起来和我们在其他地方打过的普通怪物关系更密切。"},{"uid":"410400801:44:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":45,"order":45,"actions":[{"uid":"410400801:45:1","speaker":"Kirito","text":"Really?!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"真的吗？！"},{"uid":"410400801:45:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":46,"order":46,"actions":[{"uid":"410400801:46:1","speaker":"Asuna","text":"Kirito, these monsters aren't\nHalloween-themed anymore...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人，这些怪物不再是万圣节主题了……"}]},{"id":47,"order":47,"actions":[{"uid":"410400801:47:1","speaker":"Kirito","text":"No, they're not...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不，他们不是……"}]},{"id":48,"order":48,"actions":[{"uid":"410400801:48:1","speaker":"Player C","text":"Heeeeeelp!!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家C","text_zh":"嘿嘿嘿！！"}]},{"id":49,"order":49,"actions":[{"uid":"410400801:49:1","speaker":"Kirito","text":"Hey! What happened in there?!\nWhat's going on?!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"喂！里面发生了什么？！这是怎么回事？！"}]},{"id":50,"order":50,"actions":[{"uid":"410400801:50:1","speaker":"Player C","text":"I-I've got no clue! Suddenly\nthe place was filled with types of\nmonsters we've never seen before!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家C","text_zh":"我、我不知道！突然间，这个地方充满了我们以前从未见过的各种怪物！"}]},{"id":51,"order":51,"actions":[{"uid":"410400801:51:1","speaker":"Player C","text":"They're ridiculously strong,\nand very, very angry...!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家C","text_zh":"他们太强大了，而且非常非常愤怒……！"}]},{"id":52,"order":52,"actions":[{"uid":"410400801:52:1","speaker":"Player C","text":"All the casuals have long since\nbooked it. This isn't something\nan average player can handle!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家C","text_zh":"散人早就预定了。这可不是一般的玩家能够处理的！"}]},{"id":53,"order":53,"actions":[{"uid":"410400801:53:1","speaker":"Kirito","text":"Really?!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"真的吗？！"}]},{"id":54,"order":54,"actions":[{"uid":"410400801:54:1","speaker":"Kirito","text":"The Halloween event is definitely\ngetting absorbed by the Divine\nObject quest...","pose":100115072,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"万圣节活动肯定是被神物任务吸引了……"}]},{"id":55,"order":55,"actions":[{"uid":"410400801:55:1","speaker":"Asuna","text":"It seems so...","pose":100209072,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"好像是这样……"}]},{"id":56,"order":56,"actions":[{"uid":"410400801:56:1","speaker":"Eugeo","text":"Interesting...","pose":10530207,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"有趣……"},{"uid":"410400801:56:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":57,"order":57,"actions":[{"uid":"410400801:57:1","speaker":"Eugeo","text":"So this castle's demons are slowly\nbeing replaced by monsters from\nwithin the Divine Object, huh?","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"所以这座城堡的恶魔正在慢慢被神器内部的怪物取代，是吗？"}]},{"id":58,"order":58,"actions":[{"uid":"410400801:58:1","speaker":"Eugeo","text":"Well, the only way to fix it is to\nmake it to the center of the\ncastle and get that Divine Object.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"好吧，解决这个问题的唯一方法就是到达城堡中心并拿到神器。"},{"uid":"410400801:58:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":59,"order":59,"actions":[{"uid":"410400801:59:1","speaker":"Kirito","text":"That's the short of it, yeah.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"就是这样，是的。"},{"uid":"410400801:59:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":60,"order":60,"actions":[{"uid":"410400801:60:1","speaker":"Alice","text":"Simple.\nOur task here has not changed.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"简单。我们在这里的任务没有改变。"},{"uid":"410400801:60:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":61,"order":61,"actions":[{"uid":"410400801:61:1","speaker":"Alice","text":"We will reach the heart of this\nfortress and seize the Divine\nObject for our own. That is all.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们将到达这座要塞的中心，夺取神物。仅此而已。"},{"uid":"410400801:61:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":62,"order":62,"actions":[{"uid":"410400801:62:1","speaker":"Asuna","text":"Alice, it's not going to be that\neasy. These monsters... They're\nlike nothing we've fought before.","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"爱丽丝，没那么容易。这些怪物……它们与我们之前战斗过的怪物不同。"},{"uid":"410400801:62:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":63,"order":63,"actions":[{"uid":"410400801:63:1","speaker":"Asuna","text":"I mean, all the other pla-fairies\nhave run away because it was too\nscary in there.","pose":10020909,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我是说，因为里面太可怕了，其他的妖精都跑掉了。"}]},{"id":64,"order":64,"actions":[{"uid":"410400801:64:1","speaker":"Asuna","text":"It's only the four of us.\nWe have to be careful,\nand we need a plan.","pose":10020909,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"就我们四个人。我们必须小心，我们需要一个计划。"},{"uid":"410400801:64:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":65,"order":65,"actions":[{"uid":"410400801:65:1","speaker":"Alice","text":"...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."},{"uid":"410400801:65:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":66,"order":66,"actions":[{"uid":"410400801:66:1","speaker":"Alice","text":"I was not proposing we blindly\ncharge in.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我并不是建议我们盲目冲锋。"}]},{"id":67,"order":67,"actions":[{"uid":"410400801:67:1","speaker":"Alice","text":"I am well aware that we must rely\non your knowledge and wisdom to\nlead us to victory this day.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我深知今天必须依靠你们的知识和智慧来带领我们走向胜利。"}]},{"id":68,"order":68,"actions":[{"uid":"410400801:68:1","speaker":"Alice","text":"If you need time to formulate\na strategy, say so now.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"如果你需要时间制定策略，现在就说。"}]},{"id":69,"order":69,"actions":[{"uid":"410400801:69:1","speaker":"Alice","text":"I will wait, if I must.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"如果必须的话，我会等。"},{"uid":"410400801:69:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":70,"order":70,"actions":[{"uid":"410400801:70:1","speaker":"Kirito","text":"Alice...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"爱丽丝..."},{"uid":"410400801:70:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":71,"order":71,"actions":[{"uid":"410400801:71:1","speaker":"Eugeo","text":"What she's trying to say is that\nwe trust you, and we'll follow\nyour lead.","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"她想说的是我们相信你，我们会听从你的指挥。"},{"uid":"410400801:71:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":72,"order":72,"actions":[{"uid":"410400801:72:1","speaker":"Kirito","text":"Eugeo, Alice...\nThank you for believing in us.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧、爱丽丝...感谢您对我们的信任。"},{"uid":"410400801:72:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":73,"order":73,"actions":[{"uid":"410400801:73:1","speaker":"Kirito","text":"So Alice, I'm saying so now.\nGive us some time to think\nof something.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以爱丽丝，我现在就这么说。给我们一些时间思考一些事情。"}]},{"id":74,"order":74,"actions":[{"uid":"410400801:74:1","speaker":"Kirito","text":"We'll come up with a foolproof\nplan, I promise you!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们会想出一个万无一失的计划，我向你保证！"},{"uid":"410400801:74:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":75,"order":75,"actions":[{"uid":"410400801:75:1","speaker":"Eugeo","text":"Alice and I are counting on you!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"爱丽丝和我就指望你了！"},{"uid":"410400801:75:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":76,"order":76,"actions":[{"uid":"410400801:76:1","speaker":"Alice","text":"We don't have much time.\nI request haste.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们时间不多了。我请求尽快。"},{"uid":"410400801:76:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":77,"order":77,"actions":[{"uid":"410400801:77:1","speaker":"Yui","text":"Daddy... Is this even possible?","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"爹地……这可能吗？"},{"uid":"410400801:77:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400801:77:3","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":78,"order":78,"actions":[{"uid":"410400801:78:1","speaker":"Yui","text":"I find it hard to believe a\ncarefully planned seasonal event\ncould be corrupted like this...","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"我很难相信精心策划的季节性活动会被破坏成这样......"}]},{"id":79,"order":79,"actions":[{"uid":"410400801:79:1","speaker":"Kirito","text":"But it's the only explanation.\nThe system was probably struggling\nto find a way to integrate","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但这是唯一的解释。该系统可能正在努力寻找集成方法"}]},{"id":80,"order":80,"actions":[{"uid":"410400801:80:1","speaker":"Kirito","text":"the Divine Object into the game,\nbut a tiny tweak to the Halloween\nevent let it justify the anomaly.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"神器进入游戏，但对万圣节活动的微小调整让它证明了异常现象的合理性。"}]},{"id":81,"order":81,"actions":[{"uid":"410400801:81:1","speaker":"Asuna","text":"Okay, let's put that in normal\nperson language.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"好吧，我们用正常人的语言来说吧。"}]},{"id":82,"order":82,"actions":[{"uid":"410400801:82:1","speaker":"Asuna","text":"You're saying that Cardinal\nauto-changed our regularly\nscheduled Halloween event?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你是说卡迪纳尔自动改变了我们定期安排的万圣节活动？"}]},{"id":83,"order":83,"actions":[{"uid":"410400801:83:1","speaker":"Kirito","text":"Bingo. But we can fix this.\nThe Divine Object's the problem,\nso if we can just find it and","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"宾果。但我们可以解决这个问题。 神器就是问题所在，所以如果我们能找到它并"}]},{"id":84,"order":84,"actions":[{"uid":"410400801:84:1","speaker":"Kirito","text":"get it out of the Dread Bastion,\nthe event should revert to normal\nand everyone can have fun again.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"把它带出恐惧堡垒，活动应该会恢复正常，大家又可以玩得开心了。"}]},{"id":85,"order":85,"actions":[{"uid":"410400801:85:1","speaker":"Yui","text":"But it's only the four of you,\nand the castle is filled with\nterrifying monsters...","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"但只有你们四个人，而且城堡里充满了可怕的怪物……"}]},{"id":86,"order":86,"actions":[{"uid":"410400801:86:1","speaker":"Yui","text":"It'll be next to impossible to\nreach the Divine Object...","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"到达神器几乎是不可能的……"}]},{"id":87,"order":87,"actions":[{"uid":"410400801:87:1","speaker":"Asuna","text":"Hmm... Even if we called in\neveryone we know for backup,\nI don't think we could swing it...","pose":10020909,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯……即使我们把所有认识的人都叫来支援，我想我们也无法扭转局面……"}]},{"id":88,"order":88,"actions":[{"uid":"410400801:88:1","speaker":"Kirito","text":"Yeah, there's just too many of\nthem. We need a way to keep those\nhordes of baddies off our backs...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊，太多了。我们需要一种方法来阻止那些成群结队的坏人......"}]},{"id":89,"order":89,"actions":[{"uid":"410400801:89:1","speaker":"Yui","text":"What about the Cross Switch\ntechnique you came up with,\nMommy? Will that help?","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"妈妈你想出的十字开关技术怎么样？这会有帮助吗？"}]},{"id":90,"order":90,"actions":[{"uid":"410400801:90:1","speaker":"Asuna","text":"It will, but it's only really\nuseful against a single, powerful\nmonster-not swarms of them...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"会的，但它只对单个强大的怪物有用，而不是一大群……"}]},{"id":91,"order":91,"actions":[{"uid":"410400801:91:1","speaker":"Kirito","text":"Hmm... If a Divine Object's the\nproblem, why don't we make a\nDivine Object the solution?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……如果神器是问题所在，那我们为什么不用神器来解决呢？"}]},{"id":92,"order":92,"actions":[{"uid":"410400801:92:1","speaker":"Asuna","text":"And how do you propose we do that?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"那您建议我们如何去做呢？"}]},{"id":93,"order":93,"actions":[{"uid":"410400801:93:1","speaker":"Kirito","text":"The castle monsters are trying to\ndestroy them, right?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"城堡里的怪物想要消灭他们对吧？"}]},{"id":94,"order":94,"actions":[{"uid":"410400801:94:1","speaker":"Kirito","text":"But I bet the system won't let\nrandom mobs break an item\nintended for player use.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但我敢打赌系统不会让随机小怪破坏玩家使用的物品。"}]},{"id":95,"order":95,"actions":[{"uid":"410400801:95:1","speaker":"Kirito","text":"So if the monsters want them that\nbad...","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"如果怪物那么想要他们的话……"}]},{"id":96,"order":96,"actions":[{"uid":"410400801:96:1","speaker":"Asuna","text":"Wait...\nYou're not serious... Are you?","pose":100209032,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"等等……你不是认真的……是吗？"}]},{"id":97,"order":97,"actions":[{"uid":"410400801:97:1","speaker":"Alice","text":"Kirito, Asuna... What did you do?","pose":10540108,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"桐人、亚丝娜……你做了什么？"},{"uid":"410400801:97:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":98,"order":98,"actions":[{"uid":"410400801:98:1","speaker":"Eugeo","text":"Where did all the monsters go?","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"怪物都去哪儿了？"},{"uid":"410400801:98:2","speaker":"Alice","text":"","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":99,"order":99,"actions":[{"uid":"410400801:99:1","speaker":"Kirito","text":"It looks like our plan was a\ncomplete success!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"看来我们的计划圆满成功了！"},{"uid":"410400801:99:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":100,"order":100,"actions":[{"uid":"410400801:100:1","speaker":"Alice","text":"I saw you summon several allies,\nbut it don't see them.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我看到你召唤了几个盟友，但它没有看到他们。"},{"uid":"410400801:100:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":101,"order":101,"actions":[{"uid":"410400801:101:1","speaker":"Alice","text":"Does this have something to do\nwith this plan of yours?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这和你的这个计划有关系吗？"},{"uid":"410400801:101:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":102,"order":102,"actions":[{"uid":"410400801:102:1","speaker":"Asuna","text":"Yup, that's right! We called in\nLeafa, Yuuki, and Sinonon to help\nus get rid of the monsters.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是啊，没错！我们召唤了莉法、优纪和Sinonon来帮助我们消灭怪物。"},{"uid":"410400801:102:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":103,"order":103,"actions":[{"uid":"410400801:103:1","speaker":"Asuna","text":"We gave each of them a Divine\nObject and had them fly around\nthe castle's outer walls.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们给了他们每人一件神物，让他们绕着城堡的外墙飞行。"},{"uid":"410400801:103:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":104,"order":104,"actions":[{"uid":"410400801:104:1","speaker":"Eugeo","text":"You did-WHAT is THAT?!\nThe sky is full of... Are those\nthousands of birds?!","pose":105302082,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你做了——那是什么？！天空充满了……那是成千上万只鸟吗？！"},{"uid":"410400801:104:2","speaker":"Alice","text":"","pose":10540103,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":105,"order":105,"actions":[{"uid":"410400801:105:1","speaker":"Alice","text":"H-Hold on, those aren't birds...","pose":10540103,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"等、等一下，那不是鸟……"},{"uid":"410400801:105:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":106,"order":106,"actions":[{"uid":"410400801:106:1","speaker":"Kirito","text":"Yup! It's a flying monster train,\nand our friends are the\nconductors. Choo-choo.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊！这是一列会飞的怪物火车，我们的朋友是列车员。咕咕。"},{"uid":"410400801:106:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":107,"order":107,"actions":[{"uid":"410400801:107:1","speaker":"Kirito","text":"If you squint reaaally hard,\nyou can see our friends at the\nfront of the pack.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"如果你仔细眯起眼睛，你就能看到我们的朋友在队伍的最前面。"},{"uid":"410400801:107:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":108,"order":108,"actions":[{"uid":"410400801:108:1","speaker":"Eugeo","text":"Th-They're in serious trouble!\nIf those monsters catch them,\nthey'll be torn to pieces!","pose":105302012,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"他们、他们遇到大麻烦了！如果那些怪物抓住他们，他们就会被撕成碎片！"},{"uid":"410400801:108:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":109,"order":109,"actions":[{"uid":"410400801:109:1","speaker":"Kirito","text":"Nah, they're fine. While they're\ndistracting the baddies, we slip\nin and grab the Divine Object.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不，他们很好。当他们分散坏人的注意力时，我们溜进去拿走了神器。"},{"uid":"410400801:109:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":110,"order":110,"actions":[{"uid":"410400801:110:1","speaker":"Alice","text":"They're fine? With thousands of\nbloodthirsty beasts in hot\npursuit, you say \"they're fine\"?","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"他们还好吗？成千上万的嗜血猛兽紧追不舍，你说“他们没事”？"},{"uid":"410400801:110:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":111,"order":111,"actions":[{"uid":"410400801:111:1","speaker":"Alice","text":"They are your friends, not mine,\nyet you callously risk their\nlives.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"他们是你的朋友，不是我的，你却冷酷无情地拿他们的生命冒险。"}]},{"id":112,"order":112,"actions":[{"uid":"410400801:112:1","speaker":"Alice","text":"They could die, Kirito!\nAren't you worried about them?!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"他们会死的，桐人！你不担心他们吗？！"},{"uid":"410400801:112:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":113,"order":113,"actions":[{"uid":"410400801:113:1","speaker":"Kirito","text":"Really?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"真的吗？！"},{"uid":"410400801:113:2","speaker":"Asuna","text":"","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":114,"order":114,"actions":[{"uid":"410400801:114:1","speaker":"Alice","text":"Worse, you risk the Divine Objects\nas well! They will be destroyed\nif those monsters catch them!","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"更糟糕的是，你还有神器的风险！如果那些怪物抓住他们，他们就会被消灭！"},{"uid":"410400801:114:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":115,"order":115,"actions":[{"uid":"410400801:115:1","speaker":"Asuna","text":"Alice, it's not like that...","pose":10020909,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"爱丽丝，不是这样的……"},{"uid":"410400801:115:2","speaker":"Kirito","text":"","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":116,"order":116,"actions":[{"uid":"410400801:116:1","speaker":"Kirito","text":"Okay, I obviously should have\nchosen my words better.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好吧，我显然应该更好地选择我的用词。"}]},{"id":117,"order":117,"actions":[{"uid":"410400801:117:1","speaker":"Kirito","text":"I can guarantee you that our\nfriends-and the Divine Objects-\nare in zero danger.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我可以向你保证，我们的朋友——以及神器——处于零危险状态。"}]},{"id":118,"order":118,"actions":[{"uid":"410400801:118:1","speaker":"Kirito","text":"Think of it as one of our world's\nrules. I know how it sounds,\nbut I need you to trust me here.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"把它当作我们这个世界的规则之一。我知道这听起来如何，但我需要你相信我。"},{"uid":"410400801:118:2","speaker":"Asuna","text":"","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":119,"order":119,"actions":[{"uid":"410400801:119:1","speaker":"Eugeo","text":"...Very well. I choose to believe\nin you, as I have before.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"……很好。我选择相信你，就像以前一样。"},{"uid":"410400801:119:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":120,"order":120,"actions":[{"uid":"410400801:120:1","speaker":"Alice","text":"...","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."}]},{"id":121,"order":121,"actions":[{"uid":"410400801:121:1","speaker":"Alice","text":"Understood. Time is of the\nessence, and I won't waste any\nmore of it doubting you. For now.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"明白了。时间很宝贵，我不会再浪费时间去怀疑你了。目前。"},{"uid":"410400801:121:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":122,"order":122,"actions":[{"uid":"410400801:122:1","speaker":"Asuna","text":"Thank you.\nWe won't betray your trust.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"谢谢。我们不会辜负您的信任。"},{"uid":"410400801:122:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":123,"order":123,"actions":[{"uid":"410400801:123:1","speaker":"Kirito","text":"And thank you for worrying about\nour friends. That means a lot to\nme.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"谢谢你们为我们的朋友担心。这对我来说意义重大。"},{"uid":"410400801:123:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":124,"order":124,"actions":[{"uid":"410400801:124:1","speaker":"Alice","text":"H-Hmph! I-I was more concerned\nwith the Divine Objects' safety!\nNow come on, we're wasting time!","pose":105401011,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"哼、哼！我、我更关心神器的安全！现在来吧，我们在浪费时间！"},{"uid":"410400801:124:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":125,"order":125,"actions":[{"uid":"410400801:125:1","speaker":"Kirito","text":"Yeah!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯！"},{"uid":"410400801:125:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":126,"order":126,"actions":[{"uid":"410400801:126:1","speaker":"Kirito","text":"Rrraaagh!!","pose":10011501,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呜呜！！"},{"uid":"410400801:126:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":127,"order":127,"actions":[{"uid":"410400801:127:1","speaker":"Alice","text":"Haaah!!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"哈哈哈！！"},{"uid":"410400801:127:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":128,"order":128,"actions":[{"uid":"410400801:128:1","speaker":"Monster","text":"Grrrak!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"吼啊啊！"},{"uid":"410400801:128:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410400801:128:3","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":129,"order":129,"actions":[{"uid":"410400801:129:1","speaker":"Asuna","text":"That's the last of them!","pose":10020901,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"最后一个了！"},{"uid":"410400801:129:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":130,"order":130,"actions":[{"uid":"410400801:130:1","speaker":"Eugeo","text":"We'd never have made it this far\nif all of them were here!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"如果他们都在这里的话我们根本不可能走到这一步！"},{"uid":"410400801:130:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":131,"order":131,"actions":[{"uid":"410400801:131:1","speaker":"Kirito","text":"Yeah! I owe everyone for keeping\nthose monsters distracted!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊！我欠大家让那些怪物分心！"},{"uid":"410400801:131:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":132,"order":132,"actions":[{"uid":"410400801:132:1","speaker":"Kirito","text":"Let's get moving! We should be\nalmost there!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"出发吧！我们应该快到了！"},{"uid":"410400801:132:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":133,"order":133,"actions":[{"uid":"410400801:133:1","speaker":"Alice","text":"Right!","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"对啊！"},{"uid":"410400801:133:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":134,"order":134,"actions":[{"uid":"410400801:134:1","speaker":"Yuuki","text":"Hey, Sinon? How much longer\nuntil Silica gets here?","pose":10050105,"background":"bg_event_alo_sky_night","item":"","illustration":"","speaker_zh":"优纪","text_zh":"喂，诗乃？ 西莉卡还要多久才能到达？"},{"uid":"410400801:134:2","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410400801:134:3","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":135,"order":135,"actions":[{"uid":"410400801:135:1","speaker":"Sinon","text":"No idea. She said she'd be late\nwhen Asuna contacted us, but\nI haven't heard from her since...","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"不知道。当亚丝娜联系我们时，她说她会迟到，但从那以后我就没有收到她的消息了……"}]},{"id":136,"order":136,"actions":[{"uid":"410400801:136:1","speaker":"Leafa","text":"Guys...? I think I'm running\nout of steam...","pose":100301062,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"各位……？我想我快没力气了……"}]},{"id":137,"order":137,"actions":[{"uid":"410400801:137:1","speaker":"Sinon","text":"Don't give up, Leafa! I'm sure\nthey'll be done any minute now!","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"不要放弃，莉法！我相信他们随时都会完成！"}]},{"id":138,"order":138,"actions":[{"uid":"410400801:138:1","speaker":"Leafa","text":"B-But I'm seriously exhausted...","pose":100301022,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"可、但是我真的太累了……"}]},{"id":139,"order":139,"actions":[{"uid":"410400801:139:1","speaker":"Leafa","text":"There's no flight limit in the\nsystem anymore, but a girl's got\nlimits!","pose":100301022,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"系统没有飞行限制了，但是女孩有限制！"}]},{"id":140,"order":140,"actions":[{"uid":"410400801:140:1","speaker":"Yuuki","text":"Hey Sinon, Leafa's the fastest,\nso we had her keeping the faster\nmonsters distracted...","pose":100501022,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"嘿诗乃，莉法是最快的，所以我们让她分散更快的怪物的注意力......"}]},{"id":141,"order":141,"actions":[{"uid":"410400801:141:1","speaker":"Yuuki","text":"She's been doing the lion's share\nof the work. I think we need to\ntake some of the pressure off her!","pose":100501022,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"大部分工作都是她做的。我想我们需要减轻她的压力！"}]},{"id":142,"order":142,"actions":[{"uid":"410400801:142:1","speaker":"Sinon","text":"Good thinking!\nAlright, you go... Huh?","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"好想法！好吧，你走吧……嗯？"}]},{"id":143,"order":143,"actions":[{"uid":"410400801:143:1","speaker":"Monster","text":"Graaargh...","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"吼……"}]},{"id":144,"order":144,"actions":[{"uid":"410400801:144:1","speaker":"Leafa","text":"The monsters are...leaving?","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"怪物们……离开了？"}]},{"id":145,"order":145,"actions":[{"uid":"410400801:145:1","speaker":"Yuuki","text":"That means they did it!","pose":10050103,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"那就说明他们做到了！"}]},{"id":146,"order":146,"actions":[{"uid":"410400801:146:1","speaker":"Sinon","text":"Finally. It certainly took them\nlong enough.","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"终于。他们确实花了足够长的时间。"}]},{"id":147,"order":147,"actions":[{"uid":"410400801:147:1","speaker":"Vampire","text":"I vant to suck your blood!","pose":1,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"吸血鬼","text_zh":"我要吸你的血！"},{"uid":"410400801:147:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410400801:147:3","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":148,"order":148,"actions":[{"uid":"410400801:148:1","speaker":"Werewolf","text":"Awoooooo!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"狼人","text_zh":"呜呜！！"}]},{"id":149,"order":149,"actions":[{"uid":"410400801:149:1","speaker":"Eugeo","text":"Look, Kirito! The werewolves and\nvampires are back! Hurray!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"看，桐人！狼人和吸血鬼回来了！欢呼！"},{"uid":"410400801:149:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":150,"order":150,"actions":[{"uid":"410400801:150:1","speaker":"Kirito","text":"Ha ha, look at that. Finally,\nthe Dread Bastion is back to\nnormal!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，你看那个。恐惧堡垒终于恢复正常了！"},{"uid":"410400801:150:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":151,"order":151,"actions":[{"uid":"410400801:151:1","speaker":"Alice","text":"However, it appears that claiming\nthe Divine Object hasn't cleansed\nthis fortress of its demons.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"不过，夺取神器似乎并没有清除这座要塞的恶魔。"},{"uid":"410400801:151:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":152,"order":152,"actions":[{"uid":"410400801:152:1","speaker":"Kirito","text":"Guess not. These guys kinda live\nhere, though, so I'm not surprised.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我猜不会。不过，这些人住在这里，所以我并不感到惊讶。"},{"uid":"410400801:152:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":153,"order":153,"actions":[{"uid":"410400801:153:1","speaker":"Asuna","text":"At least the Divine Object isn't\nmessing things up anymore.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"至少神器不再乱了。"}]},{"id":154,"order":154,"actions":[{"uid":"410400801:154:1","speaker":"Asuna","text":"With it gone, the Dread Bastion\nis back to the dark and spooky\nplace we...tolerate?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"随着它的消失，恐惧堡垒又回到了我们……能忍受的黑暗阴森的地方？"}]},{"id":155,"order":155,"actions":[{"uid":"410400801:155:1","speaker":"Kirito","text":"That makes four Divine Objects...","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这就是四件神器……"},{"uid":"410400801:155:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":156,"order":156,"actions":[{"uid":"410400801:156:1","speaker":"Eugeo","text":"Wait, hold up...\nSomething's still not right!","pose":10530203,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"等等，等等……还有哪里不对！"},{"uid":"410400801:156:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":157,"order":157,"actions":[{"uid":"410400801:157:1","speaker":"Alice","text":"Care to explain?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"愿意解释一下吗？"}]},{"id":158,"order":158,"actions":[{"uid":"410400801:158:1","speaker":"Eugeo","text":"The Dread Bastion's back, but what\nabout Aincrad?!","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"恐惧堡垒回来了，但是艾恩葛朗特呢？！"},{"uid":"410400801:158:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":159,"order":159,"actions":[{"uid":"410400801:159:1","speaker":"Asuna","text":"Oh yeah!\nI totally forgot about that!","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哦耶！我完全忘记了！"},{"uid":"410400801:159:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":160,"order":160,"actions":[{"uid":"410400801:160:1","speaker":"Eugeo","text":"Wasn't our original goal here to\nfind out what happened to Aincrad\nand bring it back?","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我们来这里的初衷不就是为了查出艾恩葛朗特到底发生了什么，然后把它带回来吗？"},{"uid":"410400801:160:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":161,"order":161,"actions":[{"uid":"410400801:161:1","speaker":"Kirito","text":"Ha ha ha, it was, wasn't it.","pose":100115042,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈哈，是不是。"},{"uid":"410400801:161:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":162,"order":162,"actions":[{"uid":"410400801:162:1","speaker":"Yui","text":"Hi there again! It appears that\nthe Dread Bastion's quest isn't\nover just yet.","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"您好！看来恐惧堡垒的任务还没有结束。"},{"uid":"410400801:162:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":163,"order":163,"actions":[{"uid":"410400801:163:1","speaker":"Yui","text":"I believe that completing it will\nrestore Aincrad's place in the\nsky.","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"我相信完成它将会恢复艾恩葛朗特在天空中的地位。"}]},{"id":164,"order":164,"actions":[{"uid":"410400801:164:1","speaker":"Asuna","text":"That's good to know.\nWell, that means we still have\nbusiness in the Dread Bastion!","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"很高兴知道。好吧，这意味着我们在恐惧堡垒里还有生意！"},{"uid":"410400801:164:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410400801:164:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":165,"order":165,"actions":[{"uid":"410400801:165:1","speaker":"Eugeo","text":"Great! I'm happy I get to play\naround with these hilarious\nmonsters some more!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"太好了！我很高兴能再和这些搞笑的怪物一起玩耍！"},{"uid":"410400801:165:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":166,"order":166,"actions":[{"uid":"410400801:166:1","speaker":"Alice","text":"*sigh*... I'd prefer to focus on\nfinding the next Divine Object...\nbut I suppose we have no choice.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"*叹气*...我更愿意专注于寻找下一个神器...但我想我们别无选择。"},{"uid":"410400801:166:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":167,"order":167,"actions":[{"uid":"410400801:167:1","speaker":"Kirito","text":"Great! Let's take a quick break,\nthen find our friends and thank\nthem for all their help!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"太好了！我们先休息一下，然后去找我们的朋友，感谢他们的帮助！"},{"uid":"410400801:167:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400801:167:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":168,"order":168,"actions":[{"uid":"410400801:168:1","speaker":"Asuna","text":"Sounds like a plan!","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"听起来像是一个计划！"}]}]};
